patches.content:
// inline_reply: reply field while the live notification offers one
InlineReply.ReplyField {
    Layout.fillWidth: true
    notif: root.notificationObject
    urgency: root.notificationObject.urgency
}

// inline_reply: take the keyboard only while a reply is typed in this
// popup; a click outside hands it back and the field keeps its text.
WlrLayershell.keyboardFocus: Notifications.iimpReplyComposer >= 0 ? WlrKeyboardFocus.OnDemand : WlrKeyboardFocus.None
HyprlandFocusGrab {
    windows: [root]
    active: root.visible && Notifications.iimpReplyComposer >= 0
    onCleared: Notifications.iimpReplyComposer = -1
}
